import java.lang.reflect.*;
import java.util.*;

public class Main {
    static String keTeks(Object o) throws IllegalAccessException {
        StringBuilder sb = new StringBuilder(o.getClass().getSimpleName() + "{");
        boolean pertama = true;
        for (Field f : o.getClass().getDeclaredFields()) {
            if (Modifier.isStatic(f.getModifiers())) {
                continue;
            }
            f.setAccessible(true);
            if (!pertama) {
                sb.append(", ");
            }
            sb.append(f.getName()).append("=").append(f.get(o));
            pertama = false;
        }
        return sb.append("}").toString();
    }

    public static void main(String[] args) throws Exception {
        for (Field f : Todo.class.getDeclaredFields()) {
            System.out.println(f.getName() + " : " + f.getType().getSimpleName());
        }

        Todo t = new Todo(1, "Belajar reflection");
        Field judul = Todo.class.getDeclaredField("judul");
        judul.setAccessible(true);
        System.out.println("Isi judul: " + judul.get(t));

        judul.set(t, "Judul diubah lewat reflection");
        System.out.println(t.getJudul());
        System.out.println(keTeks(t));
    }
}

