import java.lang.reflect.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Pengaturan p = new Pengaturan();
        Scanner in = new Scanner(System.in);
        while (in.hasNextLine()) {
            String[] d = in.nextLine().split("=");
            Field f = Pengaturan.class.getDeclaredField(d[0]);
            if (f.getType() == int.class) {
                f.set(p, Integer.parseInt(d[1]));
            } else if (f.getType() == boolean.class) {
                f.set(p, Boolean.parseBoolean(d[1]));
            } else {
                f.set(p, d[1]);
            }
        }
        for (Field f : Pengaturan.class.getDeclaredFields()) {
            System.out.println(f.getName() + " = " + f.get(p));
        }
    }
}

class Pengaturan {
    String tema = "terang";
    int ukuranHuruf = 14;
    boolean notifikasi = true;
}
